SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME() <> N'TTSmart_Company_V1_Test' THROW 59610,N'Chi chay tren dung database Company v1 test.',1;
IF OBJECT_ID(N'dbo.SchemaVersions',N'U') IS NOT NULL
BEGIN IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Company' AND MigrationNumber=1 AND ScriptChecksum='$(ScriptChecksum)') RETURN; THROW 59611,N'Migration 001 hoac checksum khong khop.',1; END;
BEGIN TRANSACTION;
DECLARE @lockResult int;
EXEC @lockResult=sys.sp_getapplock @Resource=N'TTSmart.Company.V1.Baseline',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=60000;
IF @lockResult<0 THROW 59612,N'Khong lay duoc application lock Company v1.',1;
IF OBJECT_ID(N'dbo.SchemaVersions',N'U') IS NOT NULL BEGIN IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Company' AND MigrationNumber=1 AND ScriptChecksum='$(ScriptChecksum)') BEGIN COMMIT; RETURN; END; THROW 59611,N'Migration 001 hoac checksum khong khop.',1; END;

CREATE TABLE dbo.SchemaVersions(SchemaVersionId uniqueidentifier NOT NULL CONSTRAINT PK_SchemaVersions PRIMARY KEY,ModuleCode nvarchar(64) NOT NULL,MigrationNumber int NOT NULL,MigrationName nvarchar(300) NOT NULL,ScriptChecksum char(64) COLLATE Latin1_General_100_BIN2 NOT NULL,AppliedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_SchemaVersions_AppliedAtUtc DEFAULT SYSUTCDATETIME(),AppliedBy nvarchar(128) NOT NULL CONSTRAINT DF_SchemaVersions_AppliedBy DEFAULT ORIGINAL_LOGIN(),CONSTRAINT UQ_SchemaVersions_Module_Number UNIQUE(ModuleCode,MigrationNumber),CONSTRAINT CK_SchemaVersions_Number CHECK(MigrationNumber>0),CONSTRAINT CK_SchemaVersions_Checksum CHECK(ScriptChecksum NOT LIKE '%[^0-9A-F]%'));
CREATE TABLE dbo.DatabaseInfo(DatabaseInfoId uniqueidentifier NOT NULL CONSTRAINT PK_DatabaseInfo PRIMARY KEY,SingletonKey tinyint NOT NULL,CompanyId uniqueidentifier NOT NULL,CompanyCode nvarchar(64) NOT NULL,DatabaseKind nvarchar(20) NOT NULL,SchemaVersion nvarchar(50) NOT NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_DatabaseInfo_CreatedAtUtc DEFAULT SYSUTCDATETIME(),UpdatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_DatabaseInfo_UpdatedAtUtc DEFAULT SYSUTCDATETIME(),Version int NOT NULL CONSTRAINT DF_DatabaseInfo_Version DEFAULT 0,RowVersion rowversion NOT NULL,CONSTRAINT UQ_DatabaseInfo_Singleton UNIQUE(SingletonKey),CONSTRAINT CK_DatabaseInfo_Singleton CHECK(SingletonKey=1),CONSTRAINT CK_DatabaseInfo_Kind CHECK(DatabaseKind=N'Company'),CONSTRAINT CK_DatabaseInfo_CompanyCode CHECK(CompanyCode NOT LIKE N'%[^A-Za-z0-9_-]%' AND LEN(CompanyCode)>0),CONSTRAINT CK_DatabaseInfo_Version CHECK(Version>=0));
CREATE TABLE dbo.MigrationRuns(MigrationRunId uniqueidentifier NOT NULL CONSTRAINT PK_MigrationRuns PRIMARY KEY,SourceSystem nvarchar(100) NOT NULL,SourceDatabase nvarchar(200) NULL,SourceCollection nvarchar(200) NULL,SourceManifestSha256 char(64) NULL,Status nvarchar(20) NOT NULL,StartedAtUtc datetime2(7) NOT NULL,FinishedAtUtc datetime2(7) NULL,Summary nvarchar(1000) NULL,CONSTRAINT CK_MigrationRuns_Status CHECK(Status IN(N'Pending',N'Running',N'Completed',N'Failed')),CONSTRAINT CK_MigrationRuns_Time CHECK(FinishedAtUtc IS NULL OR FinishedAtUtc>=StartedAtUtc),CONSTRAINT CK_MigrationRuns_Manifest CHECK(SourceManifestSha256 IS NULL OR SourceManifestSha256 NOT LIKE '%[^0-9A-F]%'));
CREATE TABLE dbo.MigrationMappings(MigrationMappingId uniqueidentifier NOT NULL CONSTRAINT PK_MigrationMappings PRIMARY KEY,MigrationRunId uniqueidentifier NOT NULL,SourceSystem nvarchar(100) NOT NULL,SourceDatabase nvarchar(200) NULL,SourceCollection nvarchar(200) NOT NULL,SourceKey nvarchar(1000) NOT NULL,SourceKeyType nvarchar(40) NOT NULL,SourcePath nvarchar(1000) NOT NULL CONSTRAINT DF_MigrationMappings_SourcePath DEFAULT N'',PreservationStatus nvarchar(20) NOT NULL,SourceHash char(64) NULL,MappingFingerprint char(64) COLLATE Latin1_General_100_BIN2 NOT NULL,TargetTable nvarchar(128) NULL,TargetId uniqueidentifier NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_MigrationMappings_CreatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_MigrationMappings_Run FOREIGN KEY(MigrationRunId) REFERENCES dbo.MigrationRuns(MigrationRunId),CONSTRAINT UQ_MigrationMappings_Fingerprint UNIQUE(MappingFingerprint),CONSTRAINT CK_MigrationMappings_Key CHECK(LEN(LTRIM(RTRIM(SourceKey)))>0),CONSTRAINT CK_MigrationMappings_KeyType CHECK(SourceKeyType IN(N'ObjectId',N'String',N'DocumentPath',N'SubdocumentPath',N'Generated')),CONSTRAINT CK_MigrationMappings_Status CHECK(PreservationStatus IN(N'Mapped',N'Archived',N'SecretStore',N'Empty',N'Blocked')),CONSTRAINT CK_MigrationMappings_Hash CHECK(SourceHash IS NULL OR SourceHash NOT LIKE '%[^0-9A-F]%'),CONSTRAINT CK_MigrationMappings_Fingerprint CHECK(MappingFingerprint NOT LIKE '%[^0-9A-F]%'));
CREATE TABLE dbo.MigrationIssues(MigrationIssueId uniqueidentifier NOT NULL CONSTRAINT PK_MigrationIssues PRIMARY KEY,MigrationRunId uniqueidentifier NULL,SourcePath nvarchar(1000) NOT NULL,TargetTable nvarchar(128) NULL,TargetId uniqueidentifier NULL,IssueCode nvarchar(100) NOT NULL,Severity nvarchar(20) NOT NULL,SafeDetail nvarchar(2000) NULL,Status nvarchar(20) NOT NULL CONSTRAINT DF_MigrationIssues_Status DEFAULT N'Open',ResolvedAtUtc datetime2(7) NULL,ResolvedBy nvarchar(128) NULL,CONSTRAINT FK_MigrationIssues_Run FOREIGN KEY(MigrationRunId) REFERENCES dbo.MigrationRuns(MigrationRunId),CONSTRAINT CK_MigrationIssues_Severity CHECK(Severity IN(N'Info',N'Warning',N'Error')),CONSTRAINT CK_MigrationIssues_Status CHECK(Status IN(N'Open',N'Resolved',N'Accepted')));
CREATE TABLE dbo.LegacyRecords(LegacyRecordId uniqueidentifier NOT NULL CONSTRAINT PK_LegacyRecords PRIMARY KEY,MigrationRunId uniqueidentifier NOT NULL,SourceDatabase nvarchar(200) NOT NULL,SourceCollection nvarchar(200) NOT NULL,SourceKey nvarchar(1000) NOT NULL,SourcePath nvarchar(1000) NOT NULL CONSTRAINT DF_LegacyRecords_SourcePath DEFAULT N'',SourceFingerprint char(64) COLLATE Latin1_General_100_BIN2 NOT NULL,CanonicalExtendedJson nvarchar(max) NOT NULL,ContentSha256 char(64) COLLATE Latin1_General_100_BIN2 NOT NULL,PreservationStatus nvarchar(20) NOT NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_LegacyRecords_CreatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_LegacyRecords_Run FOREIGN KEY(MigrationRunId) REFERENCES dbo.MigrationRuns(MigrationRunId),CONSTRAINT UQ_LegacyRecords_Source UNIQUE(MigrationRunId,SourceFingerprint),CONSTRAINT CK_LegacyRecords_Status CHECK(PreservationStatus IN(N'Archived',N'SecretStore',N'Empty',N'Blocked')),CONSTRAINT CK_LegacyRecords_Fingerprint CHECK(SourceFingerprint NOT LIKE '%[^0-9A-F]%'),CONSTRAINT CK_LegacyRecords_Hash CHECK(ContentSha256 NOT LIKE '%[^0-9A-F]%'));
CREATE TABLE dbo.MigrationFileManifests(MigrationFileManifestId uniqueidentifier NOT NULL CONSTRAINT PK_MigrationFileManifests PRIMARY KEY,MigrationRunId uniqueidentifier NOT NULL,StorageKey nvarchar(600) NOT NULL,ContentSha256 char(64) COLLATE Latin1_General_100_BIN2 NOT NULL,SizeBytes bigint NOT NULL,Status nvarchar(20) NOT NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_MigrationFileManifests_CreatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_MigrationFileManifests_Run FOREIGN KEY(MigrationRunId) REFERENCES dbo.MigrationRuns(MigrationRunId),CONSTRAINT UQ_MigrationFileManifests_Run_Key UNIQUE(MigrationRunId,StorageKey),CONSTRAINT CK_MigrationFileManifests_Key CHECK(StorageKey<>N'' AND LEFT(StorageKey,1)<>N'/' AND RIGHT(StorageKey,1)<>N'/' AND StorageKey NOT LIKE N'%..%' AND StorageKey NOT LIKE N'%//%' AND StorageKey NOT LIKE N'%\\%' AND StorageKey NOT LIKE N'%:%'),CONSTRAINT CK_MigrationFileManifests_Hash CHECK(ContentSha256 NOT LIKE '%[^0-9A-F]%'),CONSTRAINT CK_MigrationFileManifests_Size CHECK(SizeBytes>=0),CONSTRAINT CK_MigrationFileManifests_Status CHECK(Status IN(N'Present',N'Missing',N'Blocked')));
EXEC(N'CREATE FUNCTION dbo.IsValidStorageKey(@Value nvarchar(600)) RETURNS bit AS BEGIN IF @Value IS NULL OR DATALENGTH(@Value)=0 OR DATALENGTH(@Value)>1200 OR LEFT(@Value,1)=N''/'' OR RIGHT(@Value,1)=N''/'' OR CHARINDEX(NCHAR(92),@Value)>0 OR CHARINDEX(NCHAR(58),@Value)>0 OR @Value LIKE N''%//%'' RETURN 0; IF EXISTS(SELECT 1 FROM STRING_SPLIT(@Value,N''/'') WHERE value IN(N''.'',N''..'',N'''') OR DATALENGTH(value)<>DATALENGTH(RTRIM(value)) OR RIGHT(value,1)=N''.'') RETURN 0; RETURN 1; END;');
CREATE TABLE dbo.Brands(BrandId uniqueidentifier NOT NULL CONSTRAINT PK_Brands PRIMARY KEY,PublicId char(24) NOT NULL,Name nvarchar(200) NOT NULL,NormalizedName nvarchar(200) NOT NULL,Version int NOT NULL CONSTRAINT DF_Brands_Version DEFAULT 0,RowVersion rowversion NOT NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Brands_CreatedAtUtc DEFAULT SYSUTCDATETIME(),UpdatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Brands_UpdatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_Brands_PublicId UNIQUE(PublicId),CONSTRAINT UQ_Brands_NormalizedName UNIQUE(NormalizedName),CONSTRAINT CK_Brands_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%'),CONSTRAINT CK_Brands_Name CHECK(LEN(LTRIM(RTRIM(Name)))>0),CONSTRAINT CK_Brands_Version CHECK(Version>=0));
CREATE TABLE dbo.Categories(CategoryId uniqueidentifier NOT NULL CONSTRAINT PK_Categories PRIMARY KEY,PublicId char(24) NOT NULL,Name nvarchar(200) NOT NULL,NormalizedName nvarchar(200) NOT NULL,Version int NOT NULL CONSTRAINT DF_Categories_Version DEFAULT 0,RowVersion rowversion NOT NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Categories_CreatedAtUtc DEFAULT SYSUTCDATETIME(),UpdatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Categories_UpdatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_Categories_PublicId UNIQUE(PublicId),CONSTRAINT UQ_Categories_NormalizedName UNIQUE(NormalizedName),CONSTRAINT CK_Categories_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%'),CONSTRAINT CK_Categories_Name CHECK(LEN(LTRIM(RTRIM(Name)))>0),CONSTRAINT CK_Categories_Version CHECK(Version>=0));
CREATE TABLE dbo.Units(UnitId uniqueidentifier NOT NULL CONSTRAINT PK_Units PRIMARY KEY,PublicId char(24) NOT NULL,Name nvarchar(100) NOT NULL,NormalizedName nvarchar(100) NOT NULL,Symbol nvarchar(30) NOT NULL,Version int NOT NULL CONSTRAINT DF_Units_Version DEFAULT 0,RowVersion rowversion NOT NULL,CONSTRAINT UQ_Units_PublicId UNIQUE(PublicId),CONSTRAINT UQ_Units_NormalizedName UNIQUE(NormalizedName),CONSTRAINT CK_Units_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%'),CONSTRAINT CK_Units_Version CHECK(Version>=0));
CREATE TABLE dbo.Products(ProductId uniqueidentifier NOT NULL CONSTRAINT PK_Products PRIMARY KEY,PublicId char(24) NOT NULL,BrandId uniqueidentifier NULL,Code nvarchar(100) NULL,NormalizedCode nvarchar(100) NULL,Name nvarchar(500) NOT NULL,Description nvarchar(max) NULL,Version int NOT NULL CONSTRAINT DF_Products_Version DEFAULT 0,RowVersion rowversion NOT NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Products_CreatedAtUtc DEFAULT SYSUTCDATETIME(),UpdatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Products_UpdatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_Products_PublicId UNIQUE(PublicId),CONSTRAINT FK_Products_Brand FOREIGN KEY(BrandId) REFERENCES dbo.Brands(BrandId),CONSTRAINT CK_Products_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%'),CONSTRAINT CK_Products_Code CHECK((Code IS NULL AND NormalizedCode IS NULL) OR (Code IS NOT NULL AND NormalizedCode IS NOT NULL AND LEN(LTRIM(RTRIM(NormalizedCode)))>0)),CONSTRAINT CK_Products_Name CHECK(LEN(LTRIM(RTRIM(Name)))>0),CONSTRAINT CK_Products_Version CHECK(Version>=0));
CREATE UNIQUE INDEX UX_Products_NormalizedCode ON dbo.Products(NormalizedCode) WHERE NormalizedCode IS NOT NULL;
CREATE TABLE dbo.ProductVariants(ProductVariantId uniqueidentifier NOT NULL CONSTRAINT PK_ProductVariants PRIMARY KEY,PublicId char(24) NOT NULL,ProductId uniqueidentifier NOT NULL,UnitId uniqueidentifier NULL,Name nvarchar(300) NULL,Sku nvarchar(100) NULL,NormalizedSku nvarchar(100) NULL,Barcode nvarchar(100) NULL,NormalizedBarcode nvarchar(100) NULL,Position int NOT NULL CONSTRAINT DF_ProductVariants_Position DEFAULT 0,Version int NOT NULL CONSTRAINT DF_ProductVariants_Version DEFAULT 0,RowVersion rowversion NOT NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_ProductVariants_CreatedAtUtc DEFAULT SYSUTCDATETIME(),UpdatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_ProductVariants_UpdatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_ProductVariants_PublicId UNIQUE(PublicId),CONSTRAINT UQ_ProductVariants_Product_Variant UNIQUE(ProductVariantId,ProductId),CONSTRAINT FK_ProductVariants_Product FOREIGN KEY(ProductId) REFERENCES dbo.Products(ProductId),CONSTRAINT FK_ProductVariants_Unit FOREIGN KEY(UnitId) REFERENCES dbo.Units(UnitId),CONSTRAINT CK_ProductVariants_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%'),CONSTRAINT CK_ProductVariants_Sku CHECK((Sku IS NULL AND NormalizedSku IS NULL) OR (Sku IS NOT NULL AND NormalizedSku IS NOT NULL AND LEN(LTRIM(RTRIM(NormalizedSku)))>0)),CONSTRAINT CK_ProductVariants_Barcode CHECK((Barcode IS NULL AND NormalizedBarcode IS NULL) OR (Barcode IS NOT NULL AND NormalizedBarcode IS NOT NULL AND LEN(LTRIM(RTRIM(NormalizedBarcode)))>0)),CONSTRAINT CK_ProductVariants_Position CHECK(Position>=0),CONSTRAINT CK_ProductVariants_Version CHECK(Version>=0));
CREATE UNIQUE INDEX UX_ProductVariants_NormalizedSku ON dbo.ProductVariants(NormalizedSku) WHERE NormalizedSku IS NOT NULL;
CREATE UNIQUE INDEX UX_ProductVariants_NormalizedBarcode ON dbo.ProductVariants(NormalizedBarcode) WHERE NormalizedBarcode IS NOT NULL;
CREATE TABLE dbo.ProductCodes(ProductCodeId uniqueidentifier NOT NULL CONSTRAINT PK_ProductCodes PRIMARY KEY,ProductVariantId uniqueidentifier NOT NULL,CodeType nvarchar(20) NOT NULL,Code nvarchar(100) NOT NULL,NormalizedCode nvarchar(100) NOT NULL,Version int NOT NULL CONSTRAINT DF_ProductCodes_Version DEFAULT 0,RowVersion rowversion NOT NULL,CONSTRAINT FK_ProductCodes_ProductVariant FOREIGN KEY(ProductVariantId) REFERENCES dbo.ProductVariants(ProductVariantId),CONSTRAINT UQ_ProductCodes_Type_Normalized UNIQUE(CodeType,NormalizedCode),CONSTRAINT CK_ProductCodes_Type CHECK(CodeType IN(N'SKU',N'Barcode',N'Legacy',N'Other')),CONSTRAINT CK_ProductCodes_Code CHECK(LEN(LTRIM(RTRIM(NormalizedCode)))>0),CONSTRAINT CK_ProductCodes_Version CHECK(Version>=0));
CREATE TABLE dbo.ProductCategoryAssignments(ProductCategoryAssignmentId uniqueidentifier NOT NULL CONSTRAINT PK_ProductCategoryAssignments PRIMARY KEY,ProductId uniqueidentifier NOT NULL,CategoryId uniqueidentifier NOT NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_ProductCategoryAssignments_CreatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_ProductCategoryAssignments_Product FOREIGN KEY(ProductId) REFERENCES dbo.Products(ProductId),CONSTRAINT FK_ProductCategoryAssignments_Category FOREIGN KEY(CategoryId) REFERENCES dbo.Categories(CategoryId),CONSTRAINT UQ_ProductCategoryAssignments_Product_Category UNIQUE(ProductId,CategoryId));
CREATE TABLE dbo.Files(FileId uniqueidentifier NOT NULL CONSTRAINT PK_Files PRIMARY KEY,PublicId char(24) NOT NULL,StorageKey nvarchar(600) NOT NULL,ContentSha256 char(64) NOT NULL,MimeType nvarchar(150) NOT NULL,Extension nvarchar(20) NOT NULL,SizeBytes bigint NOT NULL,Status nvarchar(20) NOT NULL CONSTRAINT DF_Files_Status DEFAULT N'Active',Version int NOT NULL CONSTRAINT DF_Files_Version DEFAULT 0,RowVersion rowversion NOT NULL,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Files_CreatedAtUtc DEFAULT SYSUTCDATETIME(),DeletedAtUtc datetime2(7) NULL,CONSTRAINT UQ_Files_PublicId UNIQUE(PublicId),CONSTRAINT UQ_Files_StorageKey UNIQUE(StorageKey),CONSTRAINT CK_Files_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%'),CONSTRAINT CK_Files_StorageKey CHECK(dbo.IsValidStorageKey(StorageKey)=1),CONSTRAINT CK_Files_Hash CHECK(ContentSha256 NOT LIKE '%[^0-9A-F]%'),CONSTRAINT CK_Files_Extension CHECK(LEFT(Extension,1)=N'.' AND Extension NOT LIKE N'%[\\/:]%' AND LEN(Extension)>1),CONSTRAINT CK_Files_Size CHECK(SizeBytes>=0),CONSTRAINT CK_Files_Status CHECK(Status IN(N'Active',N'Deleted')),CONSTRAINT CK_Files_Version CHECK(Version>=0));
CREATE TABLE dbo.ProductFiles(ProductFileId uniqueidentifier NOT NULL CONSTRAINT PK_ProductFiles PRIMARY KEY,ProductId uniqueidentifier NULL,ProductVariantId uniqueidentifier NULL,FileId uniqueidentifier NOT NULL,UsageType nvarchar(30) NOT NULL,SortOrder int NOT NULL CONSTRAINT DF_ProductFiles_SortOrder DEFAULT 0,CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_ProductFiles_CreatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_ProductFiles_Product FOREIGN KEY(ProductId) REFERENCES dbo.Products(ProductId),CONSTRAINT FK_ProductFiles_ProductVariant FOREIGN KEY(ProductVariantId) REFERENCES dbo.ProductVariants(ProductVariantId),CONSTRAINT FK_ProductFiles_File FOREIGN KEY(FileId) REFERENCES dbo.Files(FileId),CONSTRAINT UQ_ProductFiles_Owner_File_Usage UNIQUE(ProductId,ProductVariantId,FileId,UsageType),CONSTRAINT CK_ProductFiles_OneOwner CHECK((ProductId IS NULL AND ProductVariantId IS NOT NULL) OR (ProductId IS NOT NULL AND ProductVariantId IS NULL)),CONSTRAINT CK_ProductFiles_Usage CHECK(UsageType IN(N'PrimaryImage',N'Image',N'Document',N'Attachment')),CONSTRAINT CK_ProductFiles_SortOrder CHECK(SortOrder>=0));
CREATE TABLE dbo.CompanySettings(CompanySettingId uniqueidentifier NOT NULL CONSTRAINT PK_CompanySettings PRIMARY KEY,SettingKey nvarchar(64) NOT NULL,SettingValue nvarchar(100) NOT NULL,ValueType nvarchar(20) NOT NULL,Version int NOT NULL CONSTRAINT DF_CompanySettings_Version DEFAULT 0,RowVersion rowversion NOT NULL,UpdatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_CompanySettings_UpdatedAtUtc DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_CompanySettings_Key UNIQUE(SettingKey),CONSTRAINT CK_CompanySettings_Key CHECK(SettingKey IN(N'AllowBranchCreateProduct',N'AllowBranchEditProduct',N'DefaultCurrency',N'ProductCodeFormat')),CONSTRAINT CK_CompanySettings_Value CHECK((SettingKey IN(N'AllowBranchCreateProduct',N'AllowBranchEditProduct') AND ValueType=N'Boolean' AND SettingValue IN(N'true',N'false')) OR (SettingKey=N'DefaultCurrency' AND ValueType=N'Currency' AND SettingValue LIKE N'[A-Z][A-Z][A-Z]') OR (SettingKey=N'ProductCodeFormat' AND ValueType=N'CodeFormat' AND SettingValue LIKE N'%[A-Za-z0-9{}_-]%')),CONSTRAINT CK_CompanySettings_Version CHECK(Version>=0));
CREATE TABLE dbo.ActivityLogs(ActivityLogId uniqueidentifier NOT NULL CONSTRAINT PK_ActivityLogs PRIMARY KEY,ActorUserId uniqueidentifier NULL,ActorType nvarchar(30) NOT NULL,CompanyId uniqueidentifier NOT NULL,SourceBranchId uniqueidentifier NULL,ActionCode nvarchar(100) NOT NULL,ResourceType nvarchar(100) NOT NULL,ResourceId uniqueidentifier NULL,CorrelationId uniqueidentifier NULL,OccurredAtUtc datetime2(7) NOT NULL CONSTRAINT DF_ActivityLogs_OccurredAtUtc DEFAULT SYSUTCDATETIME(),SafeDetail nvarchar(2000) NULL,CONSTRAINT CK_ActivityLogs_ActorType CHECK(ActorType IN(N'User',N'System',N'Migration')),CONSTRAINT CK_ActivityLogs_Action CHECK(LEN(LTRIM(RTRIM(ActionCode)))>0),CONSTRAINT CK_ActivityLogs_Redaction CHECK((SafeDetail IS NULL OR (SafeDetail NOT LIKE N'%password%' AND SafeDetail NOT LIKE N'%token%' AND SafeDetail NOT LIKE N'%connection string%'))));
CREATE TABLE dbo.ActivityLogDetails(ActivityLogDetailId uniqueidentifier NOT NULL CONSTRAINT PK_ActivityLogDetails PRIMARY KEY,ActivityLogId uniqueidentifier NOT NULL,DetailType nvarchar(20) NOT NULL,RedactedJson nvarchar(max) NULL,CONSTRAINT FK_ActivityLogDetails_Log FOREIGN KEY(ActivityLogId) REFERENCES dbo.ActivityLogs(ActivityLogId),CONSTRAINT UQ_ActivityLogDetails_Log_Type UNIQUE(ActivityLogId,DetailType),CONSTRAINT CK_ActivityLogDetails_Type CHECK(DetailType IN(N'Before',N'After')),CONSTRAINT CK_ActivityLogDetails_Redaction CHECK(RedactedJson IS NULL OR (RedactedJson NOT LIKE N'%password%' AND RedactedJson NOT LIKE N'%token%' AND RedactedJson NOT LIKE N'%connection string%')));
EXEC(N'CREATE TRIGGER dbo.TR_ActivityLogs_AppendOnly ON dbo.ActivityLogs INSTEAD OF UPDATE,DELETE AS BEGIN THROW 59614,N''ActivityLogs la append-only.'',1; END;');
EXEC(N'CREATE TRIGGER dbo.TR_ActivityLogDetails_AppendOnly ON dbo.ActivityLogDetails INSTEAD OF UPDATE,DELETE AS BEGIN THROW 59615,N''ActivityLogDetails la append-only.'',1; END;');
INSERT dbo.SchemaVersions(SchemaVersionId,ModuleCode,MigrationNumber,MigrationName,ScriptChecksum) VALUES(NEWID(),N'Company',1,N'CreateSystemMigrationAndCatalog','$(ScriptChecksum)');
COMMIT;
GO
